-- Much Wavering: a village on legs, its trades, and one of its houses.

space {
  id = "di_stilts",
  region = "dithers",
  name = "Much Wavering",
  description = "A village of thirty houses, each on its own legs, joined by duckboards and by the habit of shouting across. There is no ground. Under the houses there is water today and mud tomorrow, and the people of Much Wavering keep a boat and a pair of boots by every door and look out in the morning to see which. Smoke goes up from every roof and lies down again at once, along the reeds.",
  palette = { bg = "#0a100c", text = "#ccd0bc", dim = "#666c56", accent = "#d0c878", border = "#3a4630" },
  ambience = {
    fog { color = "#18221c", speed = 0.12, strength = 0.35 },
    steam { glyphs = "˙·∙", color = "#5a6458", rate = 0.25 },
    fireflies { glyphs = "°·", color = "#a8d8e0", rate = 0.08 },
  },

  things = {
    { name = "the houses",
      description = "Board and thatch, tarred below and limewashed above, each standing on eight oak legs with a ladder down to a landing stage. The legs are different lengths, having sunk at different speeds, and each house has been wedged level so many times that it stands on more wedge than leg.",
      things = {
        { name = "the tallest house", description = "The Reeve's. It is no bigger than the others. It has simply been wedged more often, by a family that minded more, and is now a full yard above its neighbours. They are very proud of the view. It is of the same fen." },
        { name = "the lowest house", description = "Old Noah Pym's, who says wedging is giving in. His floor is two inches under at spring tides and he sits with his feet on a stool and his pipe in his mouth, saying it will go down again. It always has." },
        { name = "the thatch", description = "Reed, a foot thick, steep, the colour of a wet fox. It lasts sixty years. Every roof in the village was cut within sight of it, and after a while the houses look less built than gathered." },
        { name = "a boat under each house", description = "Slung from the floor joists on two ropes, keel up. When the water comes they let go the ropes. When it does not, the boat is where the hens roost." },
      },
      actions = {
        { "Count the legs", say "You make it two hundred and forty. A woman on a ladder tells you it is two hundred and thirty-nine, and that everyone knows whose is missing, and that he knows they know." },
      } },
    { name = "the duckboards",
      description = "The village street. It is two planks wide and goes round three sides of a square of water, with a branch to every door. People pass each other on it by one of them stopping, turning sideways and breathing in. There is a rule about which. It is the one with less to carry, and it is argued every time.",
      things = {
        { name = "a passing place", description = "A wider bit, with a bench. Two old women have met on it and neither is giving way. They have been there since breakfast. It has turned, as it generally does, into a visit." },
        { name = "the wet plank", description = "One board, half way round, is always wet when the rest are dry. Nobody steps on it. Children are told it is where the Fen King puts his hand up to see who is in. The children step over it. So do the grown men, and they are not hurrying when they do." },
      },
      actions = {
        { "Walk all the way round", say "It takes four minutes and eleven greetings. By the time you are back where you started the first people know where you are from, what you had for breakfast and that you tried the leaping pole. They do not say how it went. They are being polite." },
      } },
    { name = "the square",
      description = "A pool in the middle of the village, forty feet across, kept clear of weed. It is the green, the market and the place of assembly. Meetings are held in boats. A man who wishes to speak stands up. The length of speeches in Much Wavering is governed by how long a man can stand up in a boat.",
      things = {
        { name = "the market boats", description = "Three punts tied nose to tail: one of eels, one of ducks' eggs and rush mats, and one with a single cabbage, guarded. Cabbage comes in from Greenhollow once a week and is spoken of as other villages speak of oranges." },
        { name = "the moot post", description = "A painted post in the middle of the pool with a brass ring at the top. On great occasions every boat in the village ties on to it and they go round. Nobody remembers what this decides. It is always carried." },
        { name = "the reflection", description = "Thirty houses on their legs, hanging upside down in still brown water, with the smoke going down. It is a neater village than the one above. The wedges do not show." },
      } },
    { name = "children on stilts",
      icon = "☺",
      description = "Six of them, going across the open water at a run, a yard above it, on poles strapped to their legs. They learn stilts before they learn shoes. One is carrying a smaller one. One is carrying a duck.",
      actions = {
        { "Ask for a go", say "They strap you on with great seriousness and stand back. You rise. You are eight feet tall and the fen is a different place from here, wider, with more in it. Then the fen comes up to meet you, slowly at first. They fish you out by the collar and tell you that was good for a first one, and the duck is handed to you to hold, as a consolation." },
      } },
    { name = "the Reeve",
      icon = "☺",
      description = "A square woman in a man's hat, standing on her landing with a notched stick, looking at the water. This is Thirza Pym, Reeve of Much Wavering. Her whole office is to say, each morning, whether it is a boat day or a boot day. She has never been wrong, and she is never asked how she knows.",
      things = {
        { name = "her notched stick", description = "She lowers it into the water, looks at where the wet comes to, and looks at the sky. Then she rings a hand bell: once for boots, twice for boats. This morning she rang it once and a half, and people have been uneasy since." },
        { name = "her hat", description = "Her father's, and his father's. The Reeve's hat. Inside the band there is a row of marks in ink, one for each time the water came over the floors. There are nine, and room for one more." },
      },
      actions = {
        { "Ask which it is today", say "\"Boots till noon,\" she says. \"Boats by four. In between, please yourself and don't complain to me.\" She looks at you. \"You came over Slodge's causeway. Was the middle up?\" You say that it was under. She nods and cuts a small notch in the stick, on the side away from the others." },
        { "Ask about the inn", say "\"The Mooring? It's about.\" She waves a hand at the whole of the fen. \"Barnaby lets go at closing and she lies where she fetches up. We find her again of an evening. You want a light for that.\" She nods towards the last post of the duckboards. \"There's generally one waiting. They like to be asked.\"" },
      } },
    { name = "a light at the last post",
      key = "di_inn_wisp",
      icon = "°",
      description = "Where the duckboards end, north of the last house, a marsh light is standing a foot above the water, pale blue and patient. It is not dusk yet. It has come early, like a cabman.",
      variants = {
        { when = flag "di_inn_found", description = "The light has gone back to its place at the last post, a foot above the water. It knows you now. When you look at it, it bobs, once, like a man touching his cap." },
      },
      actions = {
        { "Follow it", when = no(flag "di_inn_found"), set "di_inn_found", fx "sparkle",
          say "Everybody knows about marsh lights. You step off the end of the boards after it and your foot comes down on a plank you had not seen. And another. It takes you out among the reeds by a walk one board wide, round two bends, never faster than you can go, waiting at every gap. You are looking for the bog it means to drown you in when you smell beer. There is a lantern ahead, and a door, and a gangplank. It has brought you to the inn. It bobs once and goes back for the next one." },
        { "Thank it", when = flag "di_inn_found", say "It turns a slightly warmer blue. Nobody thanks them, as a rule. They have been bringing the Dithers home from the pub for a thousand years and all they have ever got for it is the reputation." },
      } },
    { name = "the washing",
      description = "Lines run from house to house over the water, on pulleys. Shirts, smocks, and a great many long woollen stockings, since everyone here wears two pairs and has a third drying.",
      things = {
        { name = "a shirt that fell", description = "It is floating in the square, arms out, going slowly round. Nobody has fetched it. It is Noah Pym's and he says it will dry when the water goes down." },
        { name = "eelskin garters", description = "Pegged in a row, grey and shining. A cure for cramp and rheumatics, worn below the knee. Everyone in the Dithers has rheumatics. Everyone in the Dithers has the garters. Nobody draws the conclusion." },
      } },
    { name = "the geese",
      description = "A flock of forty, grey, crossing the square in a line with the air of a procession that has right of way. They are the village's watchdogs, its lawn mowers and its clock. They go out at dawn and come in at dusk and everyone sets their day by it.",
      actions = { { "Stand in their way", say "The gander stops. The thirty-nine behind him stop. He lowers his neck until it is level with your knee and says one thing. You find that you have stepped back onto a passing place. The line resumes. Not one of them looks at you as it goes by." } } },
    { name = "the school boat",
      description = "A wide punt with a tarred canvas roof, tied to the north side. Six benches, a slate, and a schoolmistress with a pointer long enough to reach the back. When the water is up she poles the school round to the children. When it is down, they have a holiday, and pray for drought.",
      things = {
        { name = "the slate", description = "{i}The Dithers is bounded on the east by the Wood, on the west by the Sea, on the north by Opinion, and on the south by Tuesday.{/} They have been set to copy it out." },
        { name = "the sums", description = "{i}If the water rises an inch an hour and your father says it is nothing, how long before your mother is proved right?{/}" },
      } },
    { name = "a fen cat",
      icon = "c",
      description = "A grey tabby, sitting on a landing stage with her tail in the water. Something tugs it. She turns, hooks, and there is a small fish on the boards. She has no bait but herself. Cats in the Dithers swim as well as otters and say less about it.",
      actions = { { "Stroke her", say "Wet. Entirely wet, and cold, and smelling of pond. She purrs. You wipe your hand on your coat when she is not looking, and she is looking." } } },
    { name = "the privies",
      description = "A row of small sheds on the downstream side, each on four legs over open water, each with a heart cut in the door. The arrangement is simple and the fish on that side are noticeably larger. Nobody in Much Wavering fishes on that side." },
    { name = "the parish chest",
      description = "An iron-bound box on the Reeve's landing, chained to a leg of the house. It holds the village's records, and it floats. That was the first thing they asked of the smith.",
      things = {
        { name = "the Wavering Roll", description = "A scroll of vellum listing every time the village has moved. It has moved eleven times. When a house's legs are past wedging they build a new one a little north and step across. In six hundred years Much Wavering has walked three miles." },
        { name = "a deed", description = "{i}To Amos Pym and his heirs, one acre, more or less, wet or dry, wherever it may from time to time be found.{/}" },
        { name = "a list of Reeves", description = "Forty names, all Pym, each with the number of floods in their time. The first has no number. Beside it somebody has written: {i}it was all flood then{/}." },
      },
      actions = { { "Lift the lid", say "It is not locked. Thirza Pym watches you read the Roll with her arms folded and corrects your lips when they move wrong on a name." } } },
    { name = "the pump",
      description = "A cast-iron village pump, painted green, standing on its own little platform in the middle of forty miles of water. A gift from the Crown, in the last reign, after a report that the village had no well.",
      actions = { { "Work the handle", say "It gasps, shudders, and delivers a cupful of exactly what is underneath it. A woman passing with two buckets, which she has just filled by leaning over, says, \"Lovely, isn't it. We're very grateful.\"" } } },
    { name = "the smoke",
      description = "Peat smoke, blue and sweet, from thirty chimneys. It does not rise. It goes out sideways over the reeds in a long flat shelf, a little above head height, so that the village is always under a second, lower sky that smells of toast." },
  },

  exits = {
    { to = "di_staithe", label = "The duckboards, south", description = "Back along the bell rope to the staithe and the punt." },
    { to = "di_withy_row", label = "Withy Row", description = "The east side of the square, where the smoke is thickest and the work is done." },
    { to = "di_house", label = "No. 3, the Boards", description = "A ladder, a landing, a blue door, and somebody at the window who has seen you coming for some time." },
    { to = "di_inn", label = "Out to the Loose Mooring",
      description = "Off the end of the boards and along the hidden plank walk, to wherever the inn is tonight.",
      requires = flag "di_inn_found", hidden = true },
  },
}

space {
  id = "di_withy_row",
  region = "dithers",
  name = "Withy Row",
  description = "The working side of the village: three sheds on one long platform, with reed stacked higher than the roofs, willow rods soaking in a trough, and a smokehouse breathing out of every joint. It smells of tar, wet willow and eel. The three trades of the Dithers are carried on here, side by side, by three people who have not agreed about anything since the flood of the Reeve's grandmother.",
  palette = { bg = "#0c0f0a", text = "#d0ccb4", dim = "#6c684e", accent = "#d8b060", border = "#443c26" },
  ambience = {
    steam { glyphs = "˙·∙", color = "#6a6456", rate = 0.4 },
    flicker { color = "#e0a050", strength = 0.12 },
    dust { glyphs = "·˙", color = "#6a6448", rate = 0.3, speed = 0.4 },
  },

  things = {
    { name = "the eel smoker",
      icon = "☺",
      description = "Hepzibah Elver, a small woman the colour of her own trade, in a leather apron, splitting eels on a board with a knife worn to a sliver. She has smoked eels here for fifty years. She can tell which lode an eel came from by the taste, and which family caught it, and whether they had words that morning.",
      things = {
        { name = "her knife", description = "It was a carving knife. It is now a bright line with a handle. Her mother's. The blade has been sharpened away to nothing twice and replaced; the handle has been replaced once. She says it is the same knife and will hear no philosophy about it." },
        { name = "her hands", description = "Quick, shining, and never still. An eel is the hardest thing in the world to hold. She holds them the way you would hold a rope." },
      },
      actions = {
        { "Ask for a taste", say "She cuts a hand's length off a gold one and gives it to you on the knife. It is rich, sweet, and smoky right through, and it comes off the bone in one piece. \"Black lode,\" she says. \"Turf's eel. He'd had a good night, you can tell. They go bitter if he's been worrying.\"" },
        { "Ask about the bitten hive", say "She stops splitting. \"There's eels and there's eels,\" she says. \"Mostly they go to sea when they're grown. Some don't fancy it. Them as stay, keep growing.\" She goes back to her board. \"I'd not smoke that one. I'd not have the wood.\"" },
      } },
    { name = "the smokehouse",
      description = "A tall narrow shed, black inside and out, with a peat fire on the floor and the eels hung above it on rods, by the hundred, from knee height to the roof. The smoke goes up through them and out through the thatch. The thatch on this one roof has lasted two hundred years. Nothing will eat it.",
      things = {
        { name = "the rods", description = "Ash, each threaded through forty eels at the gill. The low ones are grey and wet. Half way up they are bronze. At the top, a week on, they are gold and stiff as walking sticks." },
        { name = "the fire", description = "Turf, laid in a ring, and on top of it a shovelful of something she keeps in a sack and does not name. It makes no flame at all. Smoking is the art of having a fire that never gets what it wants." },
        { name = "an eel at the very top", description = "Black, hard, a yard long, on a rod of its own. It was hung up by her grandmother, for luck. It has been smoked for ninety years. She says it would keep until the last trump and that the Archangel would be glad of it." },
      },
      actions = { { "Put your head in", say "You see gold, in rows, going up into the dark like organ pipes. Then your eyes shut on their own and you come out weeping, and smell of it for the rest of the week. Cats follow you. In Much Wavering this is taken as a sign of good character." } } },
    { name = "the reed cutter",
      icon = "☺",
      description = "Reuben Sedge, six feet and a bit, in thigh boots, binding reed into bundles with a twist of the wrist. He cuts from the first frost to the first cuckoo, standing in the water, with a hook. He has thatched every roof he can see. He looks at them the way a tailor looks at a street.",
      things = {
        { name = "his hook", description = "A short curved blade on a long handle. He lays the reed over with one hand and draws the hook through with the other, at the root, under the water, where he cannot see. He has all his fingers. He counts them, he says, every evening, as a courtesy." },
        { name = "his boots", description = "They come to the hip and are tied to his belt. Each one holds a gallon. He empties them at noon, out of habit, whether or not he has been in over the top." },
      },
      actions = {
        { "Ask about the reed", say "\"Cut it one year, it comes the next. Don't cut it, it rots and chokes and the bed turns to carr, and then where's your roof?\" He ties off a bundle. \"Fen wants cutting. Like hair. People think we take from it.\" He shakes his head. \"We're the barber.\"" },
        { "Ask what he finds in the beds", say "\"Nests. Otters. A boot, most years.\" He thinks. \"Bottle, once, with a letter in it from Saltwick. A man wanting news of the sea.\" He nods east. \"And lights, of a night, going home. They've a place. I don't cut near it. Barnaby'd know. It's his lamp they're so proud of.\"" },
      } },
    { name = "the reed stacks",
      description = "Bundles stood on end and built into ricks as big as houses, gold on the outside and green within, each rick with a little thatched hat of its own to keep the rain out of the reed that will keep the rain out.",
      things = {
        { name = "a bundle", description = "As thick as you can circle with your arms, six feet long, butted square on a board so every stem ends even. A good roof takes two thousand. He ties each with a band of reed twisted on itself. Nothing in the bundle is not reed." },
        { name = "a harvest mouse's nest", description = "A ball of woven leaf the size of an apple, fixed between three stems in the side of the rick. He stacked the bundle with the nest in it, on the outside, on purpose, the right way up." },
        { name = "the tally post", description = "A notch for every hundred bundles, and the year. The notches for the year of the big flood go right round the post. There was nothing to do that year but cut." },
      } },
    { name = "the basket maker",
      key = "di_basket_maker",
      icon = "☺",
      description = "Dorcas Withy, on a low plank seat with a half-made eel hive between her knees, working a rod round the stakes without looking at it. Her eyes are on you. She is a broad calm woman with grey hair pinned up with a bodkin, and she has the look of someone who knows how your story comes out and is too well bred to say.",
      things = {
        { name = "her bodkin", description = "Bone, yellow, sharp, as long as a hand. It opens the weave to take a new rod. It also holds up her hair, tests cakes, and was once shown to a bailiff, briefly, across a table." },
        { name = "her lap board", description = "Scored with the ghosts of a thousand basket bottoms, ring within ring. There is one mark that is not a ring. It is a five-pointed figure, small, scratched and then scratched out, as you might cross out the wrong word." },
      },
      actions = {
        { "Watch her work", say "In, out, in, out, a tap with the iron, turn. The rod goes round as if it had always meant to. She is not looking. \"Willow wants to be a basket,\" she says. \"All you do is stop it being a tree for a bit and it goes the rest of the way itself.\" The hive grows an inch while she says it." },
        { "Ask about Tuesdays", say "The rod stops. \"Who's been talking? Seth. It's the parcels.\" She looks you over. \"It's a reading circle. Three of us. We read a book and we have a view of it.\" The rod starts again. \"You don't come to the Holt without you've brought the book and done the reading. Mrs Mallow at number three has this month's. She's had it six weeks. You might remind her whose it is.\"" },
      } },
    { name = "the baskets",
      description = "Hung from the eaves and stacked along the platform: eel hives, fish kiddles, egg baskets, a cradle, and one enormous hamper with a lid.",
      things = {
        { name = "an eel hive", description = "Four feet long, with a funnel of sharpened rods pointing inward. An eel goes in easy and meets the points coming out. She says it is the same with most arrangements people enter into." },
        { name = "a cradle", description = "White willow, peeled, on rockers. It is tarred underneath. \"So it floats,\" she says, as if there were cradles that did not." },
        { name = "the enormous hamper", description = "Big enough for a man. Ordered by the Vigilant Society of somewhere east, for the removal of a Count. It was never collected. She keeps the washing in it." },
        { name = "a basket that holds water", description = "Woven so close that it does. She made it to settle a bet with Hepzibah Elver. It took a winter. The bet was for a penny, and the penny is nailed to the post over her seat." },
      } },
    { name = "the soaking trough",
      description = "A hollowed trunk full of water and willow rods, sorted by length: Luke, Threepenny, Long Small and Great. The rods must lie a week to be supple. A frog sits on the end of the trough, keeping the time.",
      actions = { { "Bend a rod", say "You take one out and bend it round your knee. It goes all the way, like a ribbon, and stays. You try a dry one from the stack. It snaps and hits you in the ear. Dorcas Withy does not laugh. Her shoulders do." } } },
    { name = "the osier bed",
      description = "Behind the sheds, a square of willow stools cut to the ground every winter and sprouting in a thicket of straight rods, red, yellow and green. It is the only crop in the Dithers that does not care whether it is planted in land or water." },
    { name = "the old argument",
      description = "It lives on the platform between the three sheds, like a dog. Whether the reed, the willow or the eel came first to the Dithers, and so which trade is senior. Each has a story.",
      things = {
        { name = "the smoker's story", description = "That the eels came up out of the sea before there was a fen, looking for somewhere quiet, and the fen grew round them to oblige." },
        { name = "the cutter's story", description = "That in the beginning there was one reed, and the wind blew across the top of it, and that was the first sound." },
        { name = "the basket maker's story", description = "She does not tell hers. She says she was not there, and neither were they, and that it is remarkable how many people were." },
      },
      actions = { { "Take a side", say "You say you suppose the reed. Reuben Sedge shakes your hand. Hepzibah Elver puts down her knife. Twenty minutes later you are sitting on a bundle with an eel in one hand and a basket in the other, having been given both to help you think again, and none of them has drawn breath." } } },
    { name = "a heron on the roof",
      description = "Grey, hunched, on the ridge of the smokehouse, in the smoke. It comes for the heads. It has stood there so many years that its front is a shade browner than a heron ought to be, and it is the only one in the fen that is never troubled by fleas." },
    { name = "a tar barrel",
      description = "Open, black, with a brush standing in it. Everything in Much Wavering below the floor is tarred once a year: legs, boats, cradles. The children are told to keep still and are done round.",
      actions = { { "Stir it", say "The brush comes up trailing a rope of black that will not break. It gets on your sleeve. It is on your sleeve to this day." } } },
    { name = "the turf stack",
      description = "Peat bricks under a lean-to, for the smokehouse. The Turfs bring a punt load each Friday down the black lode. The bottom bricks of the stack have never been reached. They were cut before the top ones were laid down, and no one can say by how long." },
  },

  exits = {
    { to = "di_stilts", label = "The square", description = "Back along the boards to the pool and the houses." },
  },
}

space {
  id = "di_house",
  region = "dithers",
  name = "No. 3, the Boards",
  description = "One room and a loft, on eight legs, with a floor that is very slightly a boat. It is warm, low and brown, and it smells of peat smoke and seed cake. Everything is hung up. Chairs hang on the wall, pans from the beams, and the bed is a cupboard a yard off the floor with doors. A small round woman is sitting by the fire with her feet on a box, and she had the kettle on before you reached the ladder.",
  palette = { bg = "#110e0a", text = "#d8ccb4", dim = "#766850", accent = "#e0a860", border = "#4a3a24" },
  ambience = {
    flicker { color = "#f0a050", strength = 0.2 },
    embers { glyphs = "·˙", color = "#c07030", rate = 0.08 },
  },

  things = {
    { name = "Mrs Mallow",
      key = "di_mallow",
      icon = "☺",
      description = "Keziah Mallow, widow, in a white cap and three shawls. She knits eel nets by the yard and knows the business of every house in the Dithers by the sound of its boards. Her late husband was a fowler. She speaks of him often and with affection, mostly in the matter of what he would have said about your boots.",
      things = {
        { name = "her knitting", description = "A net, on a wooden needle the size of a spoon, growing into a basket at her feet. She does not look at it. It is the wrong word, knitting, but it is hers, and you do not correct a woman who is giving you cake." },
        { name = "her shawls", description = "Grey, brown and red, in that order. She takes one off for each month of summer and has never yet got down to none." },
      },
      actions = {
        { "Accept a cup of tea", say "It is brown, strong, and tastes very faintly of the fen, as everything does. With it comes a slab of seed cake as thick as a prayer book. \"You're the one who went in off the stilts,\" she says. You ask how she knows. \"Heard it,\" she says, and nods at the floor." },
        { "Ask about the book", when = no(item "di_circle_book"), give "di_circle_book",
          say "\"Oh, lor.\" She looks at the dresser. \"The Circle's book. I've had it since the eels ran. I can't get on with it. There's a horse dies in chapter nine and I won't read past it.\" She puts it in your hands. \"You take it back to them, dear, at the Holt, past the heronry. They'll not turn away a body who's carrying the book. And if they ask what I thought,\" she lowers her voice, \"say I thought the horse was very well drawn.\"" },
        { "Ask about her husband", say "\"Eli. He went out after duck one morning in a fog and come back at night with no duck and no gun, very quiet.\" She knits a row. \"Said he'd walked on the bottom of the mere, dry shod, and seen his own punt go over his head. He never took a drop, mind. He was a truthful man. He just never went that way again.\"" },
      } },
    { name = "the hearth",
      description = "A slab of stone on a bed of clay, in the middle of a wooden house on a wooden floor. A turf fire burns on it, low and red, with no flame. It has not been out since she was married. On the night before the wedding her mother carried it across the boards in a pot.",
      things = {
        { name = "the kettle", description = "Black, on a hook, and always just short of boiling. It sings two notes. She can tell from the song how much is in it." },
        { name = "the turf basket", description = "Bricks of peat, cut by the Turfs. She puts one on with the tongs every hour, at the back, and draws one forward. The fire walks across the hearth all day and is carried back at night." },
        { name = "a toasting fork", description = "Made from an eel spear with two of the five tines broken off. The late Mr Mallow's. \"He'd not mind,\" she says. \"He liked toast.\"" },
      },
      actions = { { "Warm your hands", say "The heat comes off it steady and soft, like a cow's flank. There is nothing to watch. A turf fire does not perform. It simply goes on being warm at you until you stop being cold." } } },
    { name = "the cupboard bed",
      description = "A box bed built into the wall, with two panelled doors and a step. Inside: a mattress of reed mace that weighs nothing, a patchwork quilt, and a shelf with a candle.",
      things = {
        { name = "the quilt", description = "Hundreds of small squares, each from a garment she can name. \"That's Eli's Sunday waistcoat. That's my mother's apron. That's the Reeve's father's, he left it here once.\" She does not explain the last one and you do not ask." },
        { name = "the doors", description = "They shut from inside with a wooden peg. On the inner face of one, low down, a child has cut a row of boats with a pin. Seven boats. \"That was the flood of 'forty,\" she says. \"I was four. I'd nothing else to do for a week.\"" },
        candle { description = "A rushlight in an iron clip: a peeled rush dipped in mutton fat. It burns for twenty minutes, which she says is long enough for anybody's thoughts." },
      } },
    { name = "the dresser",
      description = "Three shelves of blue plates, a row of hooks with jugs, and two drawers. It is the only piece of furniture that stands on the floor, and it is tied to the wall, top and bottom, with rope.",
      things = {
        { name = "the plates", description = "Willow pattern, with the bridge and the three little men. She has drawn in a punt under the bridge on every one, with a pin and soot. \"They'd never have got across else.\"" },
        { name = "the left drawer", description = "String, a thimble, a box of fish hooks, a medal for something, and seven keys. There are no locks in the house. \"They're Eli's,\" she says. \"He found them, in the fowling. People drop keys in the fen. He said they must all fit something.\"" },
        { name = "the right drawer", description = "Letters, tied in a ribbon, and a newspaper from Aldmoor, eleven years old, which she is still reading. \"I don't hold with rushing at the news. Most of it's gone off by the time you'd get there.\"" },
      } },
    { name = "the things on the wall",
      description = "Every wall is hooks. If the water comes in, nothing is on the floor to mind it.",
      things = {
        { name = "two chairs", description = "Hanging by their top rails. She takes one down for you. The seat is rush, new, and the legs have a tide mark." },
        { name = "a fowling piece", description = "A duck gun nine feet long, hung on four pegs the length of the room. It took a quarter pound of shot at a loading and had to be fired from a punt, lying down. This is not the one he lost. This is the spare." },
        { name = "a pair of pattens", description = "Wooden soles on iron rings, to strap under your shoes. They lift you three inches. In Much Wavering three inches is the difference between a visit and a wade." },
        { name = "a sampler", description = "Cross stitch, by Keziah Pym, aged nine. {i}The Lord is my Shepherd. He leadeth me beside the still waters.{/} Under it, in smaller stitches: {i}and there is no getting away from them{/}." },
      } },
    { name = "the trap in the floor",
      description = "A square hatch with a ring, between the hearth and the door. You lift it and look straight down at brown water a yard below, with a bucket on a rope and a line with a float on it.",
      things = {
        { name = "the line", description = "She fishes from her chair. The float is a cork with a goose quill through it. When it dips, a bell on the mantel rings. She has caught her supper every day for thirty years without getting up." },
        { name = "something looking up", description = "A face, pale and wide, a foot under the surface. It is your own. You had forgotten that still water does that. All the same, you put the hatch back." },
      },
      actions = { { "Drop a crumb of cake", say "A ring, a swirl, and the bell on the mantel rings by itself. \"That's Old Tom,\" she says, not turning round. \"He'll have that. He don't take the hook any more, he just likes to be thought of.\"" } } },
    { name = "the window",
      description = "Four small panes facing south over the square. She sees the whole village from her chair, and there is a mirror on a bracket outside so she can see the duckboards as well, both ways.",
      things = {
        { name = "the mirror", description = "Angled just so. In it: the boards, the staithe a long way off, and the first yard of the causeway. \"I saw you at Slodge's end,\" she says. \"You held the stone very nicely.\"" },
        { name = "a jar of marsh marigolds", description = "On the sill, in a pickle jar, as yellow as butter. She changes them every day. There is always something yellow in flower in the Dithers. She says it is the fen being sorry about the rest." },
      } },
    { name = "the loft",
      description = "Up a ladder, under the thatch: apples on newspaper, a spinning wheel with no band, and the late Mr Mallow's decoys.",
      things = {
        { name = "the decoy ducks", description = "Twenty, carved from cork and painted, sitting in rows as on a pond. They are very good. They fooled ducks for forty years. One, at the end, is not painted, and when you look closely it is not carved either." },
        { name = "the apples", description = "From Greenhollow, wrinkled and sweet, each on its own square of paper, not touching. An apple is a great thing here. She gives you one. You are aware of the honour." },
      } },
    { name = "the barometer",
      description = "A long glass in a mahogany case, a wedding present. The needle points to {i}CHANGE{/}. It has never pointed to anything else. In another country this would be a fault." },
    { name = "the floor",
      description = "Elm boards, tarred underneath and caulked like a deck. In the flood of her childhood the whole house lifted off its legs and went a quarter of a mile with the family in it and the fire still in. They wedged it where it stopped. That is why number three is not between number two and number four." },
    { name = "the cat's shelf",
      description = "A board over the door with a folded blanket. Empty. The cat is out, fishing with her tail. There is a row of fish spines along the edge of the shelf, small to large, like a collection." },
  },

  exits = {
    { to = "di_stilts", label = "Down the ladder", description = "Out of the blue door and back to the boards, with a second slice in your pocket." },
  },
}
